package config

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

type Config struct {
	Listen   string             `yaml:"listen"`
	Backends map[string]Backend `yaml:"backends"`
	Peers    []string           `yaml:"peers"`
}

type Backend struct {
	// Managed backend (llama-server)
	Model     string   `yaml:"model"`      // HuggingFace ref, e.g. "Qwen/Qwen3-Coder-30B-A3B-Instruct-GGUF:Q4_K_M"
	Context   int      `yaml:"context"`    // Context window size
	GPULayers int      `yaml:"gpu_layers"` // -ngl flag
	Pooling   string   `yaml:"pooling"`    // "mean", "cls", "rank" — triggers --embedding flag
	Extra     []string `yaml:"extra"`      // Additional llama-server flags

	// External backend (Ollama, OpenAI, Anthropic, etc.)
	URL      string `yaml:"url"`      // If set, backend is external — no process management
	APIKey   string `yaml:"api_key"`  // Bearer token or x-api-key
	Provider string `yaml:"provider"` // "openai" (default) or "anthropic"
}

// IsManaged reports whether wire manages the llama-server process for this backend.
func (b Backend) IsManaged() bool { return b.URL == "" }

// IsExternal reports whether this backend is an external service.
func (b Backend) IsExternal() bool { return !b.IsManaged() }

// ValidationError describes a config validation failure.
type ValidationError struct {
	Field   string
	Message string
}

func (e *ValidationError) Error() string {
	return fmt.Sprintf("config validation: %s: %s", e.Field, e.Message)
}

// Load reads the config from disk, applies defaults, and validates it.
// Path resolution order: WIRE_CONFIG env var → XDG_CONFIG_HOME/wire/config.yaml →
// ~/.config/wire/config.yaml.
func Load() (*Config, error) {
	path := configPath()

	data, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, fmt.Errorf("config file not found at %s: %w", path, err)
		}
		return nil, fmt.Errorf("reading config %s: %w", path, err)
	}

	cfg := new(Config)
	dec := yaml.NewDecoder(bytes.NewReader(data))
	dec.KnownFields(true)
	if err := dec.Decode(cfg); err != nil {
		return nil, fmt.Errorf("parsing config %s: %w", path, err)
	}

	applyDefaults(cfg)

	if err := validate(cfg); err != nil {
		return nil, err
	}

	return cfg, nil
}

func configPath() string {
	if v := os.Getenv("WIRE_CONFIG"); v != "" {
		return v
	}
	base := os.Getenv("XDG_CONFIG_HOME")
	if base == "" {
		home, _ := os.UserHomeDir()
		base = filepath.Join(home, ".config")
	}
	return filepath.Join(base, "wire", "config.yaml")
}

func applyDefaults(cfg *Config) {
	if cfg.Listen == "" {
		cfg.Listen = ":8080"
	}
	for name, b := range cfg.Backends {
		if b.Provider == "" {
			b.Provider = "openai"
		}
		cfg.Backends[name] = b
	}
}

func validate(cfg *Config) error {
	for name, b := range cfg.Backends {
		switch {
		case b.Model != "" && b.URL != "":
			return &ValidationError{
				Field:   "backends." + name,
				Message: "cannot set both model and url",
			}
		case b.Model == "" && b.URL == "":
			return &ValidationError{
				Field:   "backends." + name,
				Message: "must set either model or url",
			}
		}
	}
	return nil
}

package process

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/exec"
	"strconv"
	"sync"
	"syscall"
	"time"

	"github.com/nogo/wire/internal/config"
)

type swapRequest struct {
	model  string
	doneCh chan error
}

type procState struct {
	mu      sync.Mutex
	backend config.Backend
	port    int
	proc    *os.Process
	healthy bool
	swapCh  chan swapRequest
}

// Manager supervises llama-server child processes for managed backends and
// health-checks external backends.
type Manager struct {
	cfg        *config.Config
	log        *slog.Logger
	cmdBuilder func(ctx context.Context, b config.Backend, port int) *exec.Cmd

	mu     sync.RWMutex
	procs  map[string]*procState
	wg     sync.WaitGroup
	cancel context.CancelFunc
}

// New creates a Manager. It does not start any processes; call Start.
func New(cfg *config.Config, log *slog.Logger) *Manager {
	m := new(Manager)
	m.cfg = cfg
	m.log = log
	m.procs = make(map[string]*procState)
	m.cmdBuilder = func(ctx context.Context, b config.Backend, port int) *exec.Cmd {
		return exec.CommandContext(ctx, "llama-server", buildArgs(b, port)...)
	}
	return m
}

// Start launches supervisor goroutines for all managed backends.
// It returns immediately; health checks happen asynchronously.
func (m *Manager) Start(ctx context.Context) error {
	ctx, cancel := context.WithCancel(ctx)
	m.cancel = cancel

	for name, b := range m.cfg.Backends {
		if !b.IsManaged() {
			continue
		}
		ps := new(procState)
		ps.backend = b
		ps.swapCh = make(chan swapRequest, 1)

		m.mu.Lock()
		m.procs[name] = ps
		m.mu.Unlock()

		m.wg.Add(1)
		go m.supervise(ctx, name)
	}
	return nil
}

// Stop cancels all managed processes and waits for them to exit.
func (m *Manager) Stop() error {
	if m.cancel != nil {
		m.cancel()
	}
	m.wg.Wait()
	return nil
}

// Healthy reports whether a backend is ready to serve requests.
// For external backends it performs a best-effort GET /health.
func (m *Manager) Healthy(name string) bool {
	m.mu.RLock()
	ps, ok := m.procs[name]
	m.mu.RUnlock()

	if ok {
		ps.mu.Lock()
		defer ps.mu.Unlock()
		return ps.healthy
	}

	b, ok := m.cfg.Backends[name]
	if !ok || !b.IsExternal() {
		return false
	}

	resp, err := http.Get(b.URL + "/health") //nolint:noctx
	if err != nil {
		// Best-effort: some external APIs don't implement /health.
		return true
	}
	defer resp.Body.Close()
	return resp.StatusCode == http.StatusOK
}

// Addr returns the base URL for a backend.
// For managed backends it returns "http://localhost:<port>".
// For external backends it returns Backend.URL.
func (m *Manager) Addr(name string) (string, bool) {
	m.mu.RLock()
	ps, ok := m.procs[name]
	m.mu.RUnlock()

	if ok {
		ps.mu.Lock()
		defer ps.mu.Unlock()
		if ps.port == 0 {
			return "", false
		}
		return fmt.Sprintf("http://localhost:%d", ps.port), true
	}

	b, ok := m.cfg.Backends[name]
	if !ok || !b.IsExternal() {
		return "", false
	}
	return b.URL, true
}

// Swap hot-swaps the model for a managed backend.
// It stops the running process, updates the model, starts a new process, and
// waits up to 120 seconds for the health check to pass.
func (m *Manager) Swap(ctx context.Context, name, model string) error {
	m.mu.RLock()
	ps, ok := m.procs[name]
	m.mu.RUnlock()

	if !ok {
		return fmt.Errorf("backend %q is not a managed backend", name)
	}

	doneCh := make(chan error, 1)
	select {
	case ps.swapCh <- swapRequest{model: model, doneCh: doneCh}:
	case <-ctx.Done():
		return ctx.Err()
	}

	select {
	case err := <-doneCh:
		return err
	case <-ctx.Done():
		return ctx.Err()
	}
}

// supervise is the per-backend restart loop. It runs until ctx is cancelled
// or max retries are exceeded.
func (m *Manager) supervise(ctx context.Context, name string) {
	defer m.wg.Done()

	m.mu.RLock()
	ps := m.procs[name]
	m.mu.RUnlock()

	defer func() {
		ps.mu.Lock()
		ps.healthy = false
		ps.proc = nil
		ps.mu.Unlock()
	}()

	const (
		maxRetries  = 5
		retryWindow = 60 * time.Second
		backoff     = 2 * time.Second
	)

	var (
		attempts    int
		windowStart = time.Now()
	)

	for {
		select {
		case <-ctx.Done():
			return
		default:
		}

		// Reset the retry counter when the window has elapsed.
		if time.Since(windowStart) > retryWindow {
			attempts = 0
			windowStart = time.Now()
		}

		if attempts >= maxRetries {
			m.log.Error("max restart retries exceeded, giving up", "backend", name)
			return
		}

		if attempts > 0 {
			m.log.Info("restarting backend", "backend", name, "attempt", attempts)
			select {
			case <-ctx.Done():
				return
			case <-time.After(backoff):
			}
		}

		attempts++

		port, err := freePort()
		if err != nil {
			m.log.Error("port allocation failed", "backend", name, "error", err)
			continue
		}

		ps.mu.Lock()
		ps.port = port
		ps.healthy = false
		backend := ps.backend
		ps.mu.Unlock()

		cmd, err := m.launch(ctx, name, backend, port)
		if err != nil {
			m.log.Error("failed to launch llama-server", "backend", name, "error", err)
			continue
		}

		ps.mu.Lock()
		ps.proc = cmd.Process
		ps.mu.Unlock()

		if err := waitHealthy(ctx, port, 120*time.Second); err != nil {
			m.log.Error("health check failed on start", "backend", name, "error", err)
			cmd.Process.Kill()
			cmd.Wait() //nolint:errcheck
			ps.mu.Lock()
			ps.proc = nil
			ps.mu.Unlock()
			continue
		}

		ps.mu.Lock()
		ps.healthy = true
		ps.mu.Unlock()
		m.log.Info("backend healthy", "backend", name, "port", port)

		exitCh := make(chan error, 1)
		go func() { exitCh <- cmd.Wait() }()

	monitor:
		for {
			select {
			case <-ctx.Done():
				// cmd.Cancel sends SIGTERM; cmd.WaitDelay gives 10s then SIGKILL.
				<-exitCh
				return

			case req := <-ps.swapCh:
				ps.mu.Lock()
				ps.healthy = false
				ps.backend.Model = req.model
				backend = ps.backend
				ps.mu.Unlock()

				cmd.Process.Signal(syscall.SIGTERM) //nolint:errcheck
				select {
				case <-exitCh:
				case <-time.After(10 * time.Second):
					cmd.Process.Kill() //nolint:errcheck
					<-exitCh
				}

				ps.mu.Lock()
				ps.proc = nil
				ps.mu.Unlock()

				newPort, portErr := freePort()
				if portErr != nil {
					req.doneCh <- portErr
					break monitor
				}

				ps.mu.Lock()
				ps.port = newPort
				ps.mu.Unlock()

				newCmd, launchErr := m.launch(ctx, name, backend, newPort)
				if launchErr != nil {
					req.doneCh <- launchErr
					break monitor
				}

				ps.mu.Lock()
				ps.proc = newCmd.Process
				ps.mu.Unlock()

				if healthErr := waitHealthy(ctx, newPort, 120*time.Second); healthErr != nil {
					newCmd.Process.Kill() //nolint:errcheck
					newCmd.Wait()         //nolint:errcheck
					ps.mu.Lock()
					ps.proc = nil
					ps.mu.Unlock()
					req.doneCh <- healthErr
					break monitor
				}

				ps.mu.Lock()
				ps.healthy = true
				ps.mu.Unlock()
				m.log.Info("swap complete", "backend", name, "port", newPort, "model", req.model)
				req.doneCh <- nil

				cmd = newCmd
				exitCh = make(chan error, 1)
				go func() { exitCh <- cmd.Wait() }()

			case exitErr := <-exitCh:
				ps.mu.Lock()
				ps.healthy = false
				ps.proc = nil
				ps.mu.Unlock()

				if ctx.Err() != nil {
					return
				}

				if exitErr != nil {
					if ee, ok := errors.AsType[*exec.ExitError](exitErr); ok {
						m.log.Warn("process exited unexpectedly", "backend", name, "exit_code", ee.ExitCode())
					} else {
						m.log.Warn("process exited unexpectedly", "backend", name, "error", exitErr)
					}
				}
				break monitor
			}
		}
		// Fall through to retry.
	}
}

// launch starts a llama-server process and wires its stdout/stderr to slog.
func (m *Manager) launch(ctx context.Context, name string, b config.Backend, port int) (*exec.Cmd, error) {
	cmd := m.cmdBuilder(ctx, b, port)

	cmd.Cancel = func() error {
		if cmd.Process == nil {
			return nil
		}
		return cmd.Process.Signal(syscall.SIGTERM)
	}
	cmd.WaitDelay = 10 * time.Second

	cmd.Stdout = &lineLogger{log: m.log, name: name}
	cmd.Stderr = &lineLogger{log: m.log, name: name}

	if err := cmd.Start(); err != nil {
		return nil, err
	}
	return cmd, nil
}

// lineLogger buffers subprocess output and emits each complete line as a slog
// debug record. It is called from cmd's internal I/O goroutine — no locking needed.
type lineLogger struct {
	log  *slog.Logger
	name string
	buf  bytes.Buffer
}

func (l *lineLogger) Write(p []byte) (int, error) {
	l.buf.Write(p)
	for {
		b := l.buf.Bytes()
		idx := bytes.IndexByte(b, '\n')
		if idx < 0 {
			break
		}
		line := string(b[:idx])
		l.buf.Next(idx + 1)
		if len(line) > 0 {
			l.log.Debug(line, "backend", l.name)
		}
	}
	return len(p), nil
}

// buildArgs constructs the llama-server command-line arguments from a Backend config.
func buildArgs(b config.Backend, port int) []string {
	args := []string{
		"-hf", b.Model,
		"--port", strconv.Itoa(port),
		"--no-webui",
	}
	if b.GPULayers > 0 {
		args = append(args, "-ngl", strconv.Itoa(b.GPULayers))
	}
	if b.Context > 0 {
		args = append(args, "-c", strconv.Itoa(b.Context))
	}
	if b.Pooling != "" {
		args = append(args, "--embedding", "--pooling", b.Pooling)
	}
	return append(args, b.Extra...)
}

// freePort finds a free TCP port by binding to :0 and immediately releasing it.
func freePort() (int, error) {
	l, err := net.Listen("tcp", ":0")
	if err != nil {
		return 0, err
	}
	port := l.Addr().(*net.TCPAddr).Port
	l.Close()
	return port, nil
}

// waitHealthy polls GET /health on the given port every second until it
// returns 200 OK, the context is cancelled, or the timeout elapses.
func waitHealthy(ctx context.Context, port int, timeout time.Duration) error {
	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	url := fmt.Sprintf("http://localhost:%d/health", port)
	client := &http.Client{Timeout: 5 * time.Second}
	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
			resp, err := client.Get(url) //nolint:noctx
			if err == nil {
				resp.Body.Close()
				if resp.StatusCode == http.StatusOK {
					return nil
				}
			}
		}
	}
}

package gateway

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"log/slog"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strings"
	"sync"
	"time"

	"github.com/nogo/wire/internal/config"
	"github.com/nogo/wire/internal/process"
)

// backendManager is the subset of process.Manager the Gateway depends on.
type backendManager interface {
	Addr(name string) (string, bool)
	Healthy(name string) bool
}

// Gateway is an HTTP reverse-proxy that routes OpenAI-compatible requests to backends.
type Gateway struct {
	cfg    *config.Config
	mgr    backendManager
	log    *slog.Logger
	rt     *routeTable
	server *http.Server
}

// New creates a Gateway backed by the given process manager.
func New(cfg *config.Config, mgr *process.Manager, log *slog.Logger) *Gateway {
	return newGateway(cfg, mgr, log)
}

func newGateway(cfg *config.Config, mgr backendManager, log *slog.Logger) *Gateway {
	g := &Gateway{cfg: cfg, mgr: mgr, log: log, rt: buildRouteTable(cfg)}

	mux := http.NewServeMux()
	mux.HandleFunc("POST /v1/chat/completions", g.handleRoute)
	mux.HandleFunc("POST /v1/completions", g.handleRoute)
	mux.HandleFunc("POST /v1/embeddings", g.handleRoute)
	mux.HandleFunc("POST /v1/rerank", g.handleRoute)
	mux.HandleFunc("GET /v1/models", g.handleModels)
	mux.HandleFunc("GET /health", g.handleHealth)

	g.server = &http.Server{Addr: cfg.Listen, Handler: mux}
	return g
}

// ListenAndServe starts the HTTP server and shuts it down when ctx is cancelled.
func (g *Gateway) ListenAndServe(ctx context.Context) error {
	errCh := make(chan error, 1)
	go func() {
		if err := g.server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			errCh <- err
		}
	}()
	select {
	case err := <-errCh:
		return err
	case <-ctx.Done():
		shutCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		return g.server.Shutdown(shutCtx)
	}
}

// handleRoute extracts the model field from the JSON body and proxies to the matching backend.
func (g *Gateway) handleRoute(w http.ResponseWriter, r *http.Request) {
	if len(g.cfg.Backends) == 0 {
		writeError(w, http.StatusInternalServerError, "server_error", "no backends configured", "no_backends")
		return
	}

	// Tee the body so the decoder and the upstream both see it.
	var captured bytes.Buffer
	tee := io.TeeReader(r.Body, &captured)
	dec := json.NewDecoder(tee)

	var payload struct {
		Model string `json:"model"`
	}
	if err := dec.Decode(&payload); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request_error", "invalid JSON: "+err.Error(), "bad_request")
		return
	}
	if payload.Model == "" {
		writeError(w, http.StatusBadRequest, "invalid_request_error", "missing model field", "bad_request")
		return
	}

	// Reconstruct full body: captured bytes (read by decoder) + rest not yet read.
	r.Body = io.NopCloser(io.MultiReader(&captured, r.Body))

	backendName, err := g.rt.resolve(payload.Model)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request_error", err.Error(), "model_not_found")
		return
	}

	if !g.mgr.Healthy(backendName) {
		writeError(w, http.StatusServiceUnavailable, "server_error", "backend unavailable", "backend_unavailable")
		return
	}

	addr, ok := g.mgr.Addr(backendName)
	if !ok {
		writeError(w, http.StatusServiceUnavailable, "server_error", "backend unavailable", "backend_unavailable")
		return
	}

	target, parseErr := url.Parse(addr)
	if parseErr != nil {
		writeError(w, http.StatusInternalServerError, "server_error", "invalid backend URL", "internal_error")
		return
	}

	rewriter := g.buildReplacer(backendName)

	proxy := &httputil.ReverseProxy{
		Rewrite: func(pr *httputil.ProxyRequest) {
			pr.SetURL(target)
			pr.Out.Host = target.Host
		},
		FlushInterval: -1,
		ModifyResponse: func(resp *http.Response) error {
			if rewriter != nil {
				resp.Header.Del("Content-Length")
				resp.ContentLength = -1
				resp.Body = io.NopCloser(&replacingReader{r: resp.Body, repl: rewriter})
			}
			return nil
		},
		ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
			g.log.Error("proxy error", "backend", backendName, "error", err)
			writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
		},
	}

	proxy.ServeHTTP(w, r)
}

// handleModels merges GET /v1/models from all backends and rewrites model IDs to backend names.
func (g *Gateway) handleModels(w http.ResponseWriter, r *http.Request) {
	type modelObj struct {
		ID      string `json:"id"`
		Object  string `json:"object"`
		Created int64  `json:"created"`
		OwnedBy string `json:"owned_by"`
	}
	type modelsResp struct {
		Object string     `json:"object"`
		Data   []modelObj `json:"data"`
	}

	var (
		mu   sync.Mutex
		data []modelObj
		wg   sync.WaitGroup
	)
	now := time.Now().Unix()

	for name := range g.cfg.Backends {
		name := name
		wg.Add(1)
		go func() {
			defer wg.Done()
			fallback := modelObj{ID: name, Object: "model", Created: now, OwnedBy: "wire"}

			addr, ok := g.mgr.Addr(name)
			if !ok {
				mu.Lock()
				data = append(data, fallback)
				mu.Unlock()
				return
			}

			ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
			defer cancel()

			req, err := http.NewRequestWithContext(ctx, http.MethodGet, addr+"/v1/models", nil)
			if err != nil {
				mu.Lock()
				data = append(data, fallback)
				mu.Unlock()
				return
			}

			resp, err := http.DefaultClient.Do(req)
			if err != nil {
				mu.Lock()
				data = append(data, fallback)
				mu.Unlock()
				return
			}
			defer resp.Body.Close()

			var mr modelsResp
			if err := json.NewDecoder(resp.Body).Decode(&mr); err != nil || len(mr.Data) == 0 {
				mu.Lock()
				data = append(data, fallback)
				mu.Unlock()
				return
			}

			entry := mr.Data[0]
			entry.ID = name
			mu.Lock()
			data = append(data, entry)
			mu.Unlock()
		}()
	}
	wg.Wait()

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(modelsResp{Object: "list", Data: data}) //nolint:errcheck
}

// handleHealth returns 200 if at least one backend is healthy, 503 otherwise.
func (g *Gateway) handleHealth(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	for name := range g.cfg.Backends {
		if g.mgr.Healthy(name) {
			w.WriteHeader(http.StatusOK)
			json.NewEncoder(w).Encode(map[string]string{"status": "ok"}) //nolint:errcheck
			return
		}
	}
	w.WriteHeader(http.StatusServiceUnavailable)
	json.NewEncoder(w).Encode(map[string]string{"status": "degraded"}) //nolint:errcheck
}

// buildReplacer creates a strings.Replacer that rewrites llama-server model name aliases
// in response bodies to the canonical backend name.
func (g *Gateway) buildReplacer(backendName string) *strings.Replacer {
	aliases := g.rt.backendAliases[backendName]
	var pairs []string
	for _, alias := range aliases {
		if alias == backendName {
			continue
		}
		pairs = append(pairs,
			`"model":"`+alias+`"`, `"model":"`+backendName+`"`,
		)
	}
	if len(pairs) == 0 {
		return nil
	}
	return strings.NewReplacer(pairs...)
}

// replacingReader wraps an io.Reader and applies a strings.Replacer to each chunk read.
// Overflow bytes (when replacement expands the chunk) are buffered internally.
type replacingReader struct {
	r    io.Reader
	repl *strings.Replacer
	buf  bytes.Buffer
}

func (rr *replacingReader) Read(p []byte) (int, error) {
	if rr.buf.Len() > 0 {
		return rr.buf.Read(p)
	}
	tmp := make([]byte, len(p))
	n, readErr := rr.r.Read(tmp)
	if n > 0 {
		replaced := []byte(rr.repl.Replace(string(tmp[:n])))
		copy(p, replaced)
		if len(replaced) > len(p) {
			rr.buf.Write(replaced[len(p):])
			return len(p), nil // defer readErr until buf is drained
		}
		return len(replaced), readErr
	}
	return 0, readErr
}

// writeError writes an OpenAI-format JSON error response.
func writeError(w http.ResponseWriter, status int, errType, message, code string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(map[string]any{ //nolint:errcheck
		"error": map[string]any{
			"message": message,
			"type":    errType,
			"code":    code,
		},
	})
}

